import { MakeLogicType, afterMount, kea, key, path, props } from 'kea'
import { loaders } from 'kea-loaders'

import { teamLogic } from 'scenes/teamLogic'

import { errorTrackingAlertsThreadsRetrieve } from '../../../generated/api'
import { ErrorTrackingAlertThreadApi } from '../../../generated/api.schemas'

export type IssueAlertThreadsLogicProps = { issueId: string }

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface issueAlertThreadsLogicValues {
    threads: ErrorTrackingAlertThreadApi[]
    threadsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface issueAlertThreadsLogicActions {
    loadThreads: () => any
    loadThreadsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadThreadsSuccess: (
        threads: ErrorTrackingAlertThreadApi[],
        payload?: any
    ) => {
        threads: ErrorTrackingAlertThreadApi[]
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface issueAlertThreadsLogicMeta {
    key: string
}

export type issueAlertThreadsLogicType = MakeLogicType<
    issueAlertThreadsLogicValues,
    issueAlertThreadsLogicActions,
    IssueAlertThreadsLogicProps,
    issueAlertThreadsLogicMeta
>

export const issueAlertThreadsLogic = kea<issueAlertThreadsLogicType>([
    path((key) => [
        'products',
        'error_tracking',
        'scenes',
        'ErrorTrackingIssueScene',
        'ScenePanel',
        'issueAlertThreadsLogic',
        key,
    ]),
    props({} as IssueAlertThreadsLogicProps),
    key((props) => props.issueId),

    loaders(({ props }) => ({
        threads: [
            [] as ErrorTrackingAlertThreadApi[],
            {
                loadThreads: async () => {
                    return await errorTrackingAlertsThreadsRetrieve(String(teamLogic.values.currentProjectId), {
                        issue_id: props.issueId,
                    })
                },
            },
        ],
    })),

    afterMount(({ actions }) => {
        actions.loadThreads()
    }),
])
